111	    /**
112	     * Authorize a request to the Horizon dashboard.
113	     *
114	     * Behavior:
115	     * - Non-production: always allowed (dev/staging convenience).
116	     * - Production with no HORIZON_DASHBOARD credentials: denied → 403.
117	     * - Production with credentials configured:
118	     *     - Missing/invalid Basic auth header → 401 + WWW-Authenticate challenge.
119	     *     - Valid credentials (constant-time compare) → allowed.
120	     *
121	     * Extracted as a static method so it can be unit-tested without standing up
122	     * the full HTTP stack. Called from the Horizon::auth closure in boot().
123	     */
124	    public static function authorizeHorizonRequest(Request $request): bool
125	    {
126	        if (! app()->isProduction()) {
127	            return true;
128	        }
129	
130	        $expectedUser = (string) config('horizon.dashboard.username', '');
131	        $expectedPassword = (string) config('horizon.dashboard.password', '');
132	
133	        // Unset credentials = sealed prod (matches prior behavior).
134	        if ($expectedUser === '' || $expectedPassword === '') {
135	            return false;
136	        }
137	
138	        $providedUser = (string) ($request->getUser() ?? '');
139	        $providedPassword = (string) ($request->getPassword() ?? '');
140	
141	        $valid = $providedUser !== ''
142	            && $providedPassword !== ''
143	            && hash_equals($expectedUser, $providedUser)
144	            && hash_equals($expectedPassword, $providedPassword);
145	
146	        if (! $valid) {
147	            // Send 401 + challenge so the browser shows the Basic auth prompt.
148	            // Returning false would yield 403 with no challenge → user is stuck.
149	            abort(401, 'Authentication required', ['WWW-Authenticate' => 'Basic realm="Horizon"']);
150	        }
151	
152	        return true;
153	    }
