155	    /**
156	     * Configure the rate limiters for the application.
157	     */
158	    protected function configureRateLimiting(): void
159	    {
160	        $throttleEnabled = (bool) config('partna.throttle.enabled', true);
161	
162	        // Health-check and ping endpoints
163	        RateLimiter::for('health-check', function (Request $request) use ($throttleEnabled) {
164	            if (! $throttleEnabled) {
165	                return Limit::none();
166	            }
167	
168	            return Limit::perMinute(60)->by($request->ip());
169	        });
170	
171	        // Public site endpoints (viewing sites, pages)
172	        RateLimiter::for('public-site', function (Request $request) use ($throttleEnabled) {
173	            if (! $throttleEnabled) {
174	                return Limit::none();
175	            }
176	
177	            return Limit::perMinute(60)
178	                ->by($request->ip())
179	                ->response(function () {
180	                    return response()->json([
181	                        'message' => 'Too many requests.  Please try again later.',
182	                    ], 429);
183	                });
184	        });
185	
186	        // Booking checkout — tighter limit because checkout hits Stripe/Square synchronously
187	        RateLimiter::for('booking-checkout', function (Request $request) use ($throttleEnabled) {
188	            if (! $throttleEnabled) {
189	                return Limit::none();
190	            }
191	
192	            return Limit::perMinute(10)
193	                ->by($request->ip())
194	                ->response(function () {
195	                    return response()->json([
196	                        'message' => 'Too many booking attempts. Please try again shortly.',
197	                    ], 429);
198	                });
199	        });
200	
201	        // Analytics endpoints (pageviews, clicks)
202	        RateLimiter::for('analytics', function (Request $request) use ($throttleEnabled) {
203	            if (! $throttleEnabled) {
204	                return Limit::none();
205	            }
206	
207	            return Limit::perMinute(120)
208	                ->by($request->ip());
209	        });
210	
211	        // Per-link click cap — secondary defense against sustained single-link spam
212	        RateLimiter::for('analytics-click', function (Request $request) use ($throttleEnabled) {
213	            if (! $throttleEnabled) {
214	                return Limit::none();
215	            }
216	
217	            $blockId = $request->input('block_id', 'unknown');
218	
219	            return Limit::perMinute(5)
220	                ->by($request->ip().':click:'.$blockId);
221	        });
222	
223	        // Customer lead submissions (form submissions)
224	        RateLimiter::for('leads', function (Request $request) use ($throttleEnabled) {
225	            if (! $throttleEnabled) {
226	                return [Limit::none()];
227	            }
228	
229	            $subdomain = $request->route('subdomain') ?? 'unknown';
230	
231	            return [
232	                // Per IP:  3 submissions per minute
233	                Limit::perMinute(3)
234	                    ->by($request->ip())
235	                    ->response(function () {
236	                        return response()->json([
237	                            'message' => 'Too many submissions. Please wait before trying again.',
238	                        ], 429);
239	                    }),
240	
241	                // Per subdomain: 100 submissions per minute (prevent abuse)
242	                Limit::perMinute(100)
243	                    ->by($subdomain)
244	                    ->response(function () {
245	                        return response()->json([
246	                            'message' => 'This site is receiving too many submissions. Please try again later.',
247	                        ], 429);
248	                    }),
249	            ];
250	        });
251	
252	        // Public waitlist submissions
253	        RateLimiter::for('waitlist', function (Request $request) use ($throttleEnabled) {
254	            if (! $throttleEnabled) {
255	                return [Limit::none()];
256	            }
257	
258	            $email = strtolower(trim((string) $request->input('email', '')));
259	            $emailKey = $email !== '' ? hash('sha256', $email) : 'unknown';
260	
261	            return [
262	                Limit::perMinute(5)
263	                    ->by('waitlist:ip:'.$request->ip())
264	                    ->response(function () {
265	                        return response()->json([
266	                            'message' => 'Too many waitlist submissions. Please try again shortly.',
267	                        ], 429);
268	                    }),
269	
270	                Limit::perHour(12)
271	                    ->by('waitlist:email:'.$emailKey)
272	                    ->response(function () {
