3	namespace App\Console\Commands;
4	
5	use Illuminate\Console\Command;
6	use Illuminate\Support\Facades\Redis;
7	
8	// V2: Diagnostic tool. Shows Redis cache hit rate, memory usage, and key counts.
9	class CacheStats extends Command
10	{
11	    protected $signature = 'cache:stats';
12	
13	    protected $description = 'Show Redis cache statistics';
14	
15	    public function handle(): int
16	    {
17	        $redis = Redis::connection('cache');
18	
19	        $info = $redis->info('stats');
20	        $memory = $redis->info('memory');
21	
22	        $this->table(
23	            ['Metric', 'Value'],
24	            [
25	                ['Keys', $redis->dbsize()],
26	                ['Memory Used', $this->formatBytes($memory['used_memory'] ?? 0)],
27	                ['Total Commands', $info['total_commands_processed'] ?? 'N/A'],
28	                ['Keyspace Hits', $info['keyspace_hits'] ?? 'N/A'],
29	                ['Keyspace Misses', $info['keyspace_misses'] ?? 'N/A'],
30	                ['Hit Rate', $this->calculateHitRate($info)],
31	            ]
32	        );
33	
34	        return 0;
35	    }
36	
37	    private function formatBytes(int $bytes): string
38	    {
39	        $units = ['B', 'KB', 'MB', 'GB'];
40	        $i = 0;
41	        while ($bytes >= 1024 && $i < count($units) - 1) {
42	            $bytes /= 1024;
43	            $i++;
44	        }
45	
46	        return round($bytes, 2).' '.$units[$i];
47	    }
48	
49	    private function calculateHitRate(array $info): string
50	    {
51	        $hits = $info['keyspace_hits'] ?? 0;
52	        $misses = $info['keyspace_misses'] ?? 0;
53	        $total = $hits + $misses;
54	
55	        if ($total === 0) {
56	            return 'N/A';
57	        }
58	
59	        return round(($hits / $total) * 100, 2).'%';
60	    }
61	}
