3	namespace App\Listeners;
4	
5	use Illuminate\Console\Events\ScheduledTaskStarting;
6	use Illuminate\Console\Scheduling\Event as ScheduledEvent;
7	use Illuminate\Support\Facades\Cache;
8	
9	// Records a "last started" timestamp per scheduled task so GET /api/health/scheduler
10	// can detect a silently-stopped cron runner. The existing onFailure() hooks only
11	// fire when a task runs AND errors — they're blind to the case where the scheduler
12	// itself is off (Laravel Cloud cron disabled, worker crashed), which produces no
13	// events and is indistinguishable from success until orphan data shows up.
14	class RecordScheduledTaskHeartbeat
15	{
16	    public const CACHE_PREFIX = 'scheduler:last_run:';
17	
18	    public function handle(ScheduledTaskStarting $event): void
19	    {
20	        $key = self::taskKey($event->task);
21	        Cache::forever(self::CACHE_PREFIX.$key, now()->toIso8601String());
22	    }
23	
24	    // Stable identifier for a scheduled task. Prefers description (set explicitly
25	    // or auto-set by Schedule::job() to the job class), falls back to the command
26	    // string with the 'artisan' prefix stripped. Normalized to cache-key-safe chars.
27	    public static function taskKey(ScheduledEvent $task): string
28	    {
29	        $raw = (string) ($task->description ?: $task->command ?: 'unknown');
30	        // Strip "'/usr/bin/php' 'artisan' foo:bar" down to "foo:bar"
31	        $raw = preg_replace('/^.*\\bartisan\\b\\s+/', '', $raw);
32	        $raw = trim($raw, " '\"");
33	
34	        return preg_replace('/[^A-Za-z0-9:_.-]+/', '_', $raw);
35	    }
36	}
